def _unique_name(Webhook, base):
    name, n = base[:255], 2
    while Webhook.objects.filter(name=name).exists():
        suffix = f" ({n})"
        name, n = base[:255 - len(suffix)] + suffix, n + 1
    return name


def _channel_for_url(Webhook, url, name):
    """Reuse a channel with exactly this URL (the oldest), or create one."""
    existing = Webhook.objects.filter(url=url).order_by("created_at", "id").first()
    if existing is not None:
        return existing
    return Webhook.objects.create(name=_unique_name(Webhook, name), url=url)


